from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
L=np.log(A)
phis=[np.ones_like(A),A,A**2,A**3,A*L]
def build(lam, extra_t):
    e=np.exp(-lam*t)
    psis=[np.ones_like(t),e]+extra_t
    return np.column_stack([p*s for p in phis for s in psis])
def nm(lam,extra):
    X=build(lam[0],extra); c=np.linalg.lstsq(X,y,rcond=None)[0]; r=y-X@c
    return np.mean(r**2)/np.var(y)
for extra_name,extra in [('none',[]),('t',[t]),('t,t2',[t,t**2])]:
    best=min((least_squares(lambda p:[np.sqrt(nm(p,extra))],[l0]).x[0],None) for l0 in [0.3,0.5,1.0])
    print(extra_name, best[0], nm([best[0]],extra))

from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
e=np.exp(-0.5*t)
def design(p):
    p_,q,r,s,lam=p
    ee=np.exp(-lam*t)
    return np.column_stack([np.ones_like(t),A**p_,t,t*A**q,t**2,t**2*A**r,ee,ee*A**s,A*np.log(A),ee*t])
def resid(p):
    X=design(p); c=np.linalg.lstsq(X,y,rcond=None)[0]; return y-X@c
rng=np.random.default_rng(0)
best=None
for k in range(40):
